// #d65b5b (6a993d6fbd1469e36cd65b5b) AC5 — у Super Admin в «מסלול ביקורת» строки «סיבת סיום» и «משך בפועל» совпадают с данными попытки;
// у приглашения без попытки — «—». Кейсы END-002 (пять причин), END-003 (ссылка без попытки). Источник истины — ответ get_attempt_audit_trail. Только чтение, десктоп.
// Открытие трассы пишет запись в журнал доступа SA (норма, D-25).
import { test, expect } from '../../fixtures';
import { openTrail, endReasonText, minSec } from './support-helpers';

const HASH = '#d65b5b · #6a993d6fbd1469e36cd65b5b';
const WITH_ATTEMPT = ['QA-C2-2110-D2', 'QA-PHONE-17fdd9-2210', 'QA-C7-2110-D3', 'QA-C4-2110-D2', 'QA-G4-A-1321'];
const NO_ATTEMPT = 'QA-534912-2110-AC2';

test.describe(`Поддержка — «סיבת סיום» и «משך בפועל» в «מסלול ביקורת» (${HASH})`, () => {
  for (const name of WITH_ATTEMPT) {
    test(`${name}: «סיבת סיום» и «משך בפועל» в панели = данным официальной попытки текущего приглашения @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const admin = await asUser('admin');
      await admin.setViewportSize({ width: 1440, height: 900 });
      const { drawer, trail } = await openTrail(admin, name);

      // Колонка 0 = текущее (последнее) приглашение; в ней — последняя завершённая официальная попытка (как строит панель).
      const invite = trail.invites[trail.invites.length - 1];
      const attempt = trail.attempts
        .filter((a) => a.invite_id === invite.id && a.attempt_type === 'official' && a.ended_at)
        .sort((a, b) => (a.ended_at ?? '').localeCompare(b.ended_at ?? ''))
        .at(-1);
      expect(attempt, `у ${name} нет завершённой официальной попытки в API — данные изменились`).toBeTruthy();

      // Источник: AC5 — те же значения, что в отчёте (и в API).
      const reason = drawer.locator('[data-testid=audit-end][data-row=reason]');
      const duration = drawer.locator('[data-testid=audit-end][data-row=duration]');
      await expect(reason.getByRole('rowheader')).toHaveText('סיבת סיום');
      await expect(duration.getByRole('rowheader')).toHaveText('משך בפועל');
      await expect(reason.getByRole('cell').first()).toHaveText(endReasonText(attempt!.end_reason));
      if (typeof attempt!.duration_seconds === 'number') {
        await expect(duration.getByRole('cell').first()).toHaveText(`${minSec(attempt!.duration_seconds)} דק׳`);
      } else {
        await expect(duration.getByRole('cell').first()).toHaveText('—');
      }
    });
  }

  test(`${NO_ATTEMPT} (ссылка без попытки): «סיבת סיום» и «משך בפועל» — «—» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.setViewportSize({ width: 1440, height: 900 });
    const { drawer, trail } = await openTrail(admin, NO_ATTEMPT);
    expect(trail.attempts, `у ${NO_ATTEMPT} появились попытки — данные изменились`).toEqual([]);

    // Источник: AC5 / S-02 «этап не наступил — «—»», не 0 и не пустая ячейка.
    await expect(drawer.locator('[data-testid=audit-end][data-row=reason]').getByRole('cell').first()).toHaveText('—');
    await expect(drawer.locator('[data-testid=audit-end][data-row=duration]').getByRole('cell').first()).toHaveText('—');
  });
});
